const obj = new Proxy({ _secret: "hidden", name: "Hariom", age: 25 }, {
  ownKeys(target) {
    return Object.keys(target).filter(k => !k.startsWith("_"))
  }
})
return {
  keys: Object.keys(obj),
  hasSecret: "_secret" in Object.getOwnPropertyNames(obj)
}
